// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CountFinding) predicate.CountFinding {
	return predicate.CountFinding(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CountFinding) predicate.CountFinding {
	return predicate.CountFinding(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CountFinding) predicate.CountFinding {
	return predicate.CountFinding(sql.NotPredicates(p))
}
